#!/bin/sh

ROOT_DIR="/workspace"
OUTPUT_DIR="$ROOT_DIR/my-task/.tmp"
mkdir -p "$OUTPUT_DIR"
OUTPUT_FILE="$OUTPUT_DIR/test-output.tap"
REWARD_FILE="/logs/verifier/reward.txt"
mkdir -p /logs/verifier

# Write test file directly to bypass git reset restoring old baked-in version
python3 << 'PYWRITE'
import base64, os
encoded = ""
content = base64.b64decode(encoded)
open("/workspace/my-task/tests/backend_behavior.test.js", "wb").write(content)
PYWRITE

sh "$ROOT_DIR/my-task/tests/run_script.sh" >"$OUTPUT_FILE" 2>&1 || true

echo "=== TAP OUTPUT ==="
cat "$OUTPUT_FILE"
echo "=== PARSER OUTPUT ==="

PARSER_OUT=$(python3 "$ROOT_DIR/my-task/tests/parser.py" "$OUTPUT_FILE" 2>/dev/null)
echo "$PARSER_OUT"

FTP_PASSED=$(echo "$PARSER_OUT" | python3 -c "
import json,sys
d=json.load(sys.stdin)
print(len(d.get('fail_to_pass',[]))+len(d.get('pass_to_pass',[])))
" 2>/dev/null || echo 0)

EXPECTED=$(python3 -c "
import json
d=json.load(open('$ROOT_DIR/my-task/tests/config.json'))
print(len(d.get('fail_to_pass',[]))+len(d.get('pass_to_pass',[])))
" 2>/dev/null || echo 0)

if [ "$FTP_PASSED" -eq "$EXPECTED" ] && [ "$EXPECTED" -gt 0 ]; then
    echo 1 > "$REWARD_FILE"
    exit 0
else
    echo 0 > "$REWARD_FILE"
    exit 1
fi
